/**
 * The three gates on a wave's basic-enemy spawn attempts, as of v29.
 *
 * Each attempt rolls its own gate, so a tick is not one uniform compare against the spawn cap:
 * the first rolls against the spawn chance, the second against a fixed threshold, the third
 * against the More Enemies battle condition.
 */
export const WAVE_UPDATE_SPAWN_BASIC_GATE_KINDS_V29 = [
  'enemySpawnChance_vs_random0_100',
  'random0_100_le_79',
  'random_float_lt_complement',
] as const

export type WaveUpdateSpawnBasicGateKindV29 = (typeof WAVE_UPDATE_SPAWN_BASIC_GATE_KINDS_V29)[number]

/** Gate 2 passes when a random integer in [0, 100) is at most 79. */
export const WAVE_UPDATE_GATE2_INT_THRESHOLD_V29 = 79 as const
export const WAVE_UPDATE_GATE2_RANDOM_EXCLUSIVE_MAX_V29 = 100 as const
export const WAVE_UPDATE_GATE2_PASS_RATE_V29 =
  (WAVE_UPDATE_GATE2_INT_THRESHOLD_V29 + 1) / WAVE_UPDATE_GATE2_RANDOM_EXCLUSIVE_MAX_V29

/** Gate 3 reads the More Enemies battle condition, which is condition index 7. */
export const WAVE_UPDATE_MORE_ENEMIES_CONDITION_INDEX_V29 = 7 as const

/**
 * Gate 3's pass rate when More Enemies heat is inactive.
 *
 * It passes when a random fraction is below one minus the More Enemies resistance. With no heat
 * that resistance is 1, so the gate never passes.
 */
export const WAVE_UPDATE_GATE3_COMPLEMENT_PASS_RATE_V29 = 0 as const

/** The wave-spawn timer spends 0.125 s per spawn attempt. */
export const WAVE_SPAWN_TIMER_QUANTUM_SECONDS_V29 = 0.125 as const

/** The double-spawn threshold's base for the [600, 799]-style band; other themes differ. */
export const WAVE_SPAWN_DOUBLE_CHANCE_BASE_THRESHOLD_V29 = 5 as const

/** Each new wave adds the current tier divided by this to the double-spawn chance. */
export const WAVE_SPAWN_DOUBLE_CHANCE_TIER_DIVISOR_V29 = 2.85 as const
